from pathlib import Path
import tempfile, zipfile, hashlib, subprocess, json
root=Path(__file__).resolve().parent.parent
# D-054 (v0.5.0): the Source ZIP holds the source, docs and evidence needed to rebuild and audit this
# version. Browser screenshots (docs/*/screenshots, regenerated by the suites) and earlier releases'
# standalone HTML (kept in git history, their tags and GitHub Releases) are left out so the ZIP stays
# under GitHub's 100 MB file limit now that painted hubs make every screenshot ~2 MB.
def packaged(p):
    rel=p.relative_to(root).parts
    if any(part in {'.git','node_modules','test-output','__pycache__','build'} for part in rel) or p.suffix=='.zip' or 'SHA256SUMS' in p.name: return False
    if len(rel)>=3 and rel[0]=='docs' and rel[2]=='screenshots': return False
    # D-087 (v0.9.1 fixes): the reference images of the art work packs (docs/*/art/*/references) are left out as well —
    # each pack's generator script rebuilds them from src/assets, and they stay in git (ZIP 100.1 MB -> under the limit).
    if len(rel)>=5 and rel[0]=='docs' and rel[2]=='art' and 'references' in rel[3:]: return False
    # D-066 (v0.6.1): the built HTML (index.html and this release's standalone) is left out too — `npm run build`
    # regenerates both byte-identically and the standalone ships as its own release asset (ZIP 90 MB -> ~54 MB).
    if rel==('index.html',) or (rel[0]=='releases' and p.suffix=='.html'): return False
    return True
version=json.loads((root/'package.json').read_text())['version']
release=root/'releases'
# v2.2.1 (D-125): until a release candidate is packaged its HTML is not in git (builds stay in build/). Then there is
# nothing to verify yet; once releases/Ashen_Crown_v<version>.html is tracked, every check below must pass.
import sys
if '--candidate' not in sys.argv and not subprocess.run(['git','ls-files','--error-unmatch',f'releases/Ashen_Crown_v{version}.html'],cwd=root,capture_output=True).returncode==0:
    print(f'v{version} is not packaged yet (releases/Ashen_Crown_v{version}.html is not in git): release verification skipped.');sys.exit(0)
manifest={}
for line in (release/f'Ashen_Crown_v{version}_SHA256SUMS').read_text().splitlines():
    digest,name=line.split('  ',1)
    assert name not in manifest, f'Duplicate checksum: {name}'
    manifest[name]=digest
    assert hashlib.sha256((release/name).read_bytes()).hexdigest()==digest,name
assert set(manifest)=={f'Ashen_Crown_v{version}{suffix}' for suffix in ('.html','_Source.zip','_Test_Report.md')}
assert json.loads((release/'SHA256SUMS.json').read_text())==manifest
with tempfile.TemporaryDirectory() as tmp:
    with zipfile.ZipFile(release/f'Ashen_Crown_v{version}_Source.zip') as archive:
        # Validate all packaged source/docs/evidence, not only rebuilt HTML.
        expected={p.relative_to(root).as_posix():p for p in root.rglob('*') if p.is_file() and packaged(p)}
        assert set(archive.namelist())=={'ashen-crown/'+name for name in expected}, 'ZIP/current file coverage differs'
        for name,p in expected.items():
            assert archive.read('ashen-crown/'+name)==p.read_bytes(), f'ZIP/current mismatch: {name}'
        archive.extractall(tmp)
    source=Path(tmp)/'ashen-crown'
    subprocess.run(['node','scripts/build.mjs'],cwd=source,check=True)
    built=(source/'build'/'Ashen_Crown.html').read_bytes()
    assert built==(release/f'Ashen_Crown_v{version}.html').read_bytes(), 'release HTML rebuild differs'
    assert built==(root/'index.html').read_bytes(), 'index.html rebuild differs'
    tested=subprocess.run(['npm','test'],cwd=source,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    if tested.returncode:
        print(tested.stdout)
        tested.check_returncode()
print('SHA256/text+JSON manifests, exact ZIP/current source/docs/evidence, clean byte-identical HTML rebuild and unit tests: PASS')
